// Interactive onboarding simulation. No account, message or credential is sent to a server.
let activeAccount=null,pendingAction=null,onboardChallenge=null,onboardStep='profile';
function accountToolbar(){return activeAccount?`${button(tr('Mon espace','My workspace'),'account-space','text-button')}${button(tr('Déconnexion','Log out'),'logout','text-button')}`:`${button(tr('Créer mon compte','Create account'),'register','text-button')}${button(tr('Me connecter','Log in'),'login','text-button')}`}
function needsAccount(run,phone=false){const p=state.profile[state.role],c=p.contacts||{},v=p.verified||{};if(activeAccount===state.role&&c.email&&v.email===c.email&&(!phone||(c.phone&&v.phone===c.phone)))return false;pendingAction={role:state.role,run,phone};openOnboarding();return true}
function openOnboarding(login=false){onboardChallenge=null;if(!state.role){state.modal={type:login?'login-role':'register-role'};render();return}const p=state.profile[state.role],c=p.contacts||{},v=p.verified||{};onboardStep=login?'login':!c.firstName||!c.lastName||!c.city||!c.email||state.role==='employer'&&!c.companyName?'profile':v.email!==c.email||activeAccount!==state.role?'email':pendingAction?.role===state.role&&pendingAction.phone&&(!c.phone||v.phone!==c.phone)?'phone':'profile';state.modal={type:'onboarding'};render();focusModal()}
function continueOnboarding(){const p=state.profile[state.role],c=p.contacts||{},v=p.verified||{};if(v.email!==c.email){onboardStep='email';onboardChallenge=null;state.modal={type:'onboarding'};render();return}activeAccount=state.role;if(pendingAction?.role===state.role&&pendingAction.phone&&(!c.phone||v.phone!==c.phone)){onboardStep='phone';onboardChallenge=null;render();return}state.modal=null;const todo=pendingAction?.role===state.role?pendingAction:null;if(todo)pendingAction=null;onboardChallenge=null;if(todo){state.role=todo.role;todo.run()}else{state.tab='profile';render();toast(tr('Compte de démonstration prêt.','Demo account ready.'))}}
function onboardingModal(){const m=state.modal;let body='';if(m.type.endsWith('-role')){const login=m.type==='login-role';body=`<p>${tr('Choisissez votre espace. Vous pouvez aussi continuer à explorer sans compte.','Choose your workspace. You can also keep browsing without an account.')}</p><div class="card-actions">${button(tr('Je suis employé','I’m a worker'),(login?'login-role:':'register-role:')+'employee')}${button(tr('Je suis employeur','I’m an employer'),(login?'login-role:':'register-role:')+'employer')}</div>`}else{const p=state.profile[state.role],c=p.contacts||{};const input=(name,fr,en,type='text',required=true)=>`<label>${tr(fr,en)}${required?' *':''}<input name="${name}" type="${type}" value="${esc(c[name]||'')}" maxlength="120" ${required?'required':''} autocomplete="off"></label>`;const fee=state.role==='employer'?tr('Contacts : 19 $ à la pièce ou forfaits dès 49 $/mois proposés, avant taxes. Aucun achat dans cette démo.','Contacts: proposed $19 one-off or plans from $49/month before tax. No purchase in this demo.'):tr('L’espace employé est gratuit.','The worker space is free.');body=`<p class="notice">${tr('Démo : coordonnées fictives uniquement. Aucun vrai compte, courriel, SMS ou appel. Aucun mot de passe réel demandé.','Demo: fictional details only. No real account, email, SMS or call. No real password requested.')}</p><p>${fee}</p>${pendingAction?`<p class="pill">${tr('Votre action est conservée dans cet onglet.','Your action is saved in this tab.')}</p>`:''}`;if(onboardStep==='profile')body+=`<form data-form="onboard-profile"><h3>${tr(state.role==='employer'?'Votre entreprise, en quelques champs':'Votre profil, en quelques champs',state.role==='employer'?'Your business, a few details':'Your profile, a few details')}</h3><div class="form-grid">${state.role==='employer'?input('companyName','Nom de l’entreprise','Business name'):''}${input('firstName',state.role==='employer'?'Prénom du responsable':'Prénom',state.role==='employer'?'Contact first name':'First name')}${input('lastName','Nom de famille','Last name')}${input('email','Courriel','Email','email')}${input('street','Numéro et rue (facultatif)','Street address (optional)','text',false)}${input('city','Ville','City')}${input('province','Province (facultatif)','Province (optional)','text',false)}${input('country','Pays (facultatif)','Country (optional)','text',false)}${input('postal','Code postal (facultatif)','Postal code (optional)','text',false)}</div><p>${tr('L’adresse complète n’est pas nécessaire pour commencer. Le téléphone sera demandé avant une première mise en relation.','A full address is not needed to start. A phone will be requested before your first connection.')}</p><button class="primary">${tr('Continuer vers la vérification','Continue to verification')}</button></form>`;else if(onboardStep==='login')body+=`<form data-form="onboard-login"><h3>${tr('Reprendre mon compte de démonstration','Resume my demo account')}</h3><p>${tr('Seuls les comptes créés dans cet onglet sont disponibles. Une actualisation les efface.','Only accounts created in this tab are available. Reloading clears them.')}</p><label>${tr('Courriel du compte','Account email')}<input name="email" type="email" required autocomplete="off"></label><button class="primary">${tr('Continuer','Continue')}</button></form>${button(tr('Créer plutôt un compte','Create an account instead'),'register','text-button')}`;else{const phone=onboardStep==='phone';body+=`<h3>${phone?tr('Confirmer mon téléphone','Confirm my phone'):tr('Confirmer mon courriel','Confirm my email')}</h3><p>${tr('Cette vérification confirme l’accès à une coordonnée; elle ne certifie pas l’identité légale.','This verifies access to a contact channel; it does not certify legal identity.')}</p>${onboardChallenge?`<form data-form="onboard-code"><p>${esc(onboardChallenge.target)} · ${onboardChallenge.method==='call'?tr('Appel vocal simulé','Simulated voice call'):onboardChallenge.method==='sms'?'SMS':tr('Courriel','Email')}</p><div class="notice">${tr('Code de test','Test code')} : <strong id="onboard-test-code">${onboardChallenge.code}</strong><br>${tr('5 minutes · 5 essais maximum','5 minutes · 5 attempts maximum')}</div><label>${tr('Code à 6 chiffres','6-digit code')}<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="off"></label><button class="primary">${tr('Valider et continuer','Verify and continue')}</button></form>`:`<form data-form="onboard-send">${phone?input('phone','Téléphone : 10 chiffres (4505551234 ou 450-555-1234)','Phone: 10 digits (4505551234 or 450-555-1234)','tel'): `<p>${esc(c.email)}</p>`}${phone?`<label>${tr('Méthode','Method')}<select name="method"><option value="sms">SMS</option><option value="call">${tr('Appel vocal','Voice call')}</option></select></label>`:''}<button class="primary">${tr('Afficher le code simulé','Show simulated code')}</button></form>`}`}}
return `<div class="modal-shade"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${tr('Continuer avec Dispo','Continue with Dispo')}</h2><button class="close" data-action="close-modal" aria-label="${tr('Fermer','Close')}">×</button></div>${body}<div style="margin-top:20px">${button(tr('Continuer à explorer','Keep browsing'),'close-modal','text-button')}</div></section></div>`}
function onboardingSubmit(type,f){const p=state.profile[state.role];p.contacts||={};p.verified||={};if(type==='onboard-profile'){for(const key of ['firstName','lastName','email','city',...(state.role==='employer'?['companyName']:[])])if(!String(f.get(key)||'').trim()){toast(tr('Complétez les champs obligatoires.','Complete required fields.'));return}const email=String(f.get('email')).trim().toLowerCase();if(email!==p.contacts.email)delete p.verified.email;for(const key of ['firstName','lastName','street','city','province','postal','country','companyName'])if(f.has(key))p.contacts[key]=String(f.get(key)).trim();p.contacts.email=email;continueOnboarding()}if(type==='onboard-login'){if(!p.registered||String(f.get('email')).trim().toLowerCase()!==p.contacts.email){toast(tr('Aucun compte de démonstration correspondant dans cet onglet. Créez un compte pour essayer.','No matching demo account in this tab. Create an account to try it.'));return}onboardStep='email';onboardChallenge=null;render()}if(type==='onboard-send'){const phone=onboardStep==='phone';if(phone){const value=normalizePhone(String(f.get('phone')).trim());if(!DispoStandards.phone(value)){toast(tr('Entre 10 chiffres : 4505551234 ou 450-555-1234.','Enter 10 digits: 4505551234 or 450-555-1234.'));return}if(value!==p.contacts.phone)delete p.verified.phone;p.contacts.phone=value}const bytes=new Uint32Array(1);crypto.getRandomValues(bytes);onboardChallenge={kind:phone?'phone':'email',method:phone?String(f.get('method')):'email',target:phone?p.contacts.phone:p.contacts.email,code:String(100000+bytes[0]%900000),sent:Date.now(),attempts:0};render()}if(type==='onboard-code'){const c=onboardChallenge;if(!c)return;if(Date.now()-c.sent>300000||p.contacts[c.kind]!==c.target){onboardChallenge=null;render();toast(tr('Code expiré. Demandez un autre code.','Code expired. Request another code.'));return}if(String(f.get('code'))!==c.code){c.attempts++;if(c.attempts>=5){onboardChallenge=null;render()}toast(tr('Code incorrect.','Incorrect code.'));return}p.verified[c.kind]=c.target;p.registered=true;onboardChallenge=null;continueOnboarding()}}
function visitorProfile(){return `<section class="panel"><h2>${tr('Découvrez avant de vous inscrire.','Explore before signing up.')}</h2><p>${tr('Les annonces, les forfaits et la FAQ sont consultables librement. Créez votre profil lorsque vous souhaitez publier ou entrer en contact.','Browse posts, pricing and FAQs freely. Create your profile when you want to publish or connect.')}</p>${button(tr('Créer mon compte','Create account'),'register')} ${button(tr('Me connecter','Log in'),'login','secondary')}</section>`}
